def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    for r in range(h - 1):
        for c in range(w - 1):
            if (grid[r][c] == grid[r][c+1] ==
                grid[r+1][c] == grid[r+1][c+1] == 2):
                corners = [
                    (r-1, c-1,  0,  0, grid[r+2][c-1] if r+2 < h and c-1 >= 0 else 0),
                    (r-1, c+2,  0,  0, grid[r-1][c-1] if r-1 >= 0 and c-1 >= 0 else 0),
                    (r+2, c-1,  0,  0, grid[r+2][c+2] if r+2 < h and c+2 < w else 0),
                    (r+2, c+2,  0,  0, grid[r-1][c+2] if r-1 >= 0 and c+2 < w else 0),
                ]
                # Each ray's color is taken from the corresponding adjacent
                # diagonal marker, in the cyclic order seen around the block.
                positions = [(r-1,c-1), (r-1,c+2), (r+2,c-1), (r+2,c+2)]
                source_positions = [(r+2,c-1), (r-1,c-1), (r+2,c+2), (r-1,c+2)]
                directions = [(-1,-1), (-1,1), (1,-1), (1,1)]
                for (sr, sc), (cr, cc), (dr, dc) in zip(positions, source_positions, directions):
                    if 0 <= cr < h and 0 <= cc < w:
                        color = grid[cr][cc]
                        rr, col = sr, sc
                        while 0 <= rr < h and 0 <= col < w:
                            out[rr][col] = color
                            rr += dr
                            col += dc

    return out
